function Bang() {
  const data = [
    { ten: "An", diem: 8 },
    { ten: "Binh", diem: 6 },
  ];
  return (
    <table>
      <tbody>
        {data.map((d, i) => (
          <tr key={i}>
            <td>{d.ten}</td>
            <td>{d.diem}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export default Bang;
